    const host=section.querySelector('#sx-installment-schedule'),form=host.querySelector('#sx-schedule-change-form');if(!form)return;const rowsNode=form.querySelector('#sx-schedule-change-rows'),totalNode=form.querySelector('#sx-schedule-total'),refreshTotal=()=>{let total=0;for(const row of rowsNode.querySelectorAll('.sx-schedule-row')){try{total+=parseQarMinor(row.querySelector('[name=amount]').value);}catch{}}totalNode.textContent=`${tr('Replacement total','إجمالي الأقساط البديلة')}: ${money(total,data.currency)} / ${money(data.schedule.reschedulableMinor,data.currency)}`;};rowsNode.querySelectorAll('.sx-schedule-row').forEach(row=>{const remove=document.createElement('button');remove.type='button';remove.textContent=tr('Remove date','إزالة الموعد');remove.addEventListener('click',()=>{row.remove();refreshTotal();});row.append(remove);});rowsNode.addEventListener('input',refreshTotal);form.querySelector('#sx-schedule-add-row').addEventListener('click',()=>{const row=document.createElement('div');row.className='grid sx-schedule-row';row.innerHTML=`<label>${tr('New due date','تاريخ الاستحقاق الجديد')}<input type="date" name="dueDate" required></label><label>${tr('Installment amount (QAR)','قيمة القسط (ر.ق)')}<input name="amount" inputmode="decimal" required><button type="button" data-remove-schedule-row>${tr('Remove date','إزالة الموعد')}</button></label>`;rowsNode.append(row);row.querySelector('[data-remove-schedule-row]').addEventListener('click',()=>{row.remove();refreshTotal();});});form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('[type=submit]'),installments=[...rowsNode.querySelectorAll('.sx-schedule-row')].map(row=>({dueDate:row.querySelector('[name=dueDate]').value,amountMinor:parseQarMinor(row.querySelector('[name=amount]').value)})),total=installments.reduce((sum,item)=>sum+item.amountMinor,0);if(total!==data.schedule.reschedulableMinor){const error=document.createElement('p');error.className='error';error.textContent=tr('Replacement total must exactly match the eligible unpaid amount.','يجب أن يساوي الإجمالي البديل مبلغ الأقساط غير المدفوعة المؤهل تمامًا.');form.querySelector('.actions').append(error);return;}button.disabled=true;try{const path=`${mode==='owner'?'':'/accountant'}/invoices/${encodeURIComponent(data.id)}/schedule-changes`;await invoiceWrite(mode,path,{requestKey:crypto.randomUUID(),expectedVersion:data.schedule.version,reason:form.elements.reason.value,installments},csrf);await loadInvoiceDetail(card,mode,csrf,data.id);const status=card.closest('#sx-finance-screen')?.querySelector('#sx-finance-message');if(status)status.innerHTML=`<div class="success" role="status">${tr('Schedule change submitted. It will apply after a different authorized person approves it.','تم إرسال طلب تغيير الجدول. سيُطبّق بعد اعتماده من مستخدم مخوّل آخر.')}</div>`;}catch(error){const messageNode=document.createElement('p');messageNode.className='error';messageNode.setAttribute('role','alert');messageNode.textContent=message(error.message);form.querySelector('.actions').append(messageNode);button.disabled=false;}});
